CREATE PROCEDURE [dbo].[jsFetchSap]  AS  BEGIN      SET NOCOUNT ON;        DECLARE @ServerName NVARCHAR(100);      DECLARE @OilDatabase NVARCHAR(100);      DECLARE @BeverageDatabase NVARCHAR(100);   DECLARE @MartDatabase NVARCHAR(100);        SELECT @ServerName = ConfigValue FROM jsConfiguration WHERE ConfigKey = 'ServerName';      SELECT @OilDatabase = ConfigValue FROM jsConfiguration WHERE ConfigKey = 'OilDatabase';      SELECT @BeverageDatabase = ConfigValue FROM jsConfiguration WHERE ConfigKey = 'BeverageDatabase';   SELECT @MartDatabase = ConfigValue FROM jsConfiguration WHERE ConfigKey = 'MartDatabase';      DECLARE @SQL NVARCHAR(MAX);        BEGIN TRY          DELETE FROM jsVariety;          DELETE FROM jsExpenseEffectiveMonth;          DELETE FROM jsBudget;          DELETE FROM jsSubBudget;          DELETE FROM jsState;    DELETE FROM jsBranch      --variety                   SET @SQL = '              INSERT INTO jsVariety (varietyId, varietyName, company, validFrom, validTo, active, ccOwner, uCoOwner)              SELECT *               FROM OPENQUERY([' + @ServerName + '],                   ''SELECT "PrcCode", "PrcName", 1, "ValidFrom", "ValidTo", "Active", "CCOwner", "U_Co_Owner"                   FROM ' + @OilDatabase + '.OPRC                    WHERE "DimCode" = 1 AND "PrcName" IS NOT NULL'')';          EXEC sp_executesql @SQL;      SET @SQL = '              INSERT INTO jsVariety (varietyId, varietyName, company, validFrom, validTo, active, ccOwner, uCoOwner)              SELECT *               FROM OPENQUERY([' + @ServerName + '],                   ''SELECT "PrcCode", "PrcName", 2, "ValidFrom", "ValidTo", "Active", "CCOwner", "U_Co_Owner"                   FROM ' + @BeverageDatabase + '.OPRC                    WHERE "DimCode" = 1 AND "PrcName" IS NOT NULL'')';          EXEC sp_executesql @SQL;      SET @SQL = '              INSERT INTO jsVariety (varietyId, varietyName, company, validFrom, validTo, active, ccOwner, uCoOwner)              SELECT *               FROM OPENQUERY([' + @ServerName + '],                   ''SELECT "PrcCode", "PrcName", 3, "ValidFrom", "ValidTo", "Active", "CCOwner", "U_Co_Owner"                   FROM ' + @MartDatabase + '.OPRC                    WHERE "DimCode" = 1 AND "PrcName" IS NOT NULL'')';          EXEC sp_executesql @SQL;          --effmonth            SET @SQL = '              INSERT INTO jsExpenseEffectiveMonth (exEffMonthId, exEffMonthName, company, validFrom, validTo, active, ccOwner, uCoOwner)              SELECT *               FROM OPENQUERY([' + @ServerName + '],                   ''SELECT "PrcCode", "PrcName", 1, "ValidFrom", "ValidTo", "Active", "CCOwner", "U_Co_Owner"                   FROM ' + @OilDatabase + '.OPRC                    WHERE "DimCode" = 2'')';          EXEC sp_executesql @SQL;       SET @SQL = '              INSERT INTO jsExpenseEffectiveMonth (exEffMonthId, exEffMonthName, company, validFrom, validTo, active, ccOwner, uCoOwner)              SELECT *               FROM OPENQUERY([' + @ServerName + '],                   ''SELECT "PrcCode", "PrcName", 2, "ValidFrom", "ValidTo", "Active", "CCOwner", "U_Co_Owner"                   FROM ' + @BeverageDatabase + '.OPRC                    WHERE "DimCode" = 2'')';          EXEC sp_executesql @SQL;       SET @SQL = '              INSERT INTO jsExpenseEffectiveMonth (exEffMonthId, exEffMonthName, company, validFrom, validTo, active, ccOwner, uCoOwner)              SELECT *               FROM OPENQUERY([' + @ServerName + '],                   ''SELECT "PrcCode", "PrcName", 3, "ValidFrom", "ValidTo", "Active", "CCOwner", "U_Co_Owner"                   FROM ' + @MartDatabase + '.OPRC                    WHERE "DimCode" = 2'')';          EXEC sp_executesql @SQL;      --budget            SET @SQL = '              INSERT INTO jsBudget (budgetId, budgetName, company, validFrom, validTo, active, ccOwner, uCoOwner)              SELECT *               FROM OPENQUERY([' + @ServerName + '],                   ''SELECT "PrcCode