base + '.OPRC                    WHERE "DimCode" = 4'')';          EXEC sp_executesql @SQL;      SET @SQL = '              INSERT INTO jsSubBudget (sBudgetId, sBudgetName, company, validFrom, validTo, active, ccOwner, uCoOwner)              SELECT *               FROM OPENQUERY([' + @ServerName + '],                   ''SELECT "PrcCode", "PrcName", 3, "ValidFrom", "ValidTo", "Active", "CCOwner", "U_Co_Owner"                   FROM ' + @MartDatabase + '.OPRC                    WHERE "DimCode" = 4'')';          EXEC sp_executesql @SQL;        --state            SET @SQL = '              INSERT INTO jsState (stateId, stateName, company, validFrom, validTo, active, ccOwner, uCoOwner)              SELECT *               FROM OPENQUERY([' + @ServerName + '],                   ''SELECT "PrcCode", "PrcName", 1, "ValidFrom", "ValidTo", "Active", "CCOwner", "U_Co_Owner"                   FROM ' + @OilDatabase + '.OPRC                    WHERE "DimCode" = 5'')';          EXEC sp_executesql @SQL;      SET @SQL = '              INSERT INTO jsState (stateId, stateName, company, validFrom, validTo, active, ccOwner, uCoOwner)              SELECT *               FROM OPENQUERY([' + @ServerName + '],                   ''SELECT "PrcCode", "PrcName", 2, "ValidFrom", "ValidTo", "Active", "CCOwner", "U_Co_Owner"                   FROM ' + @BeverageDatabase + '.OPRC                    WHERE "DimCode" = 5'')';          EXEC sp_executesql @SQL;      SET @SQL = '              INSERT INTO jsState (stateId, stateName, company, validFrom, validTo, active, ccOwner, uCoOwner)              SELECT *               FROM OPENQUERY([' + @ServerName + '],                   ''SELECT "PrcCode", "PrcName", 3, "ValidFrom", "ValidTo", "Active", "CCOwner", "U_Co_Owner"                   FROM ' + @MartDatabase + '.OPRC                    WHERE "DimCode" = 5'')';          EXEC sp_executesql @SQL;      --branch      SET @SQL = '              INSERT INTO jsBranch (branchId, branchName,company)              SELECT *               FROM OPENQUERY([' + @ServerName + '],                   ''SELECT "BPLId", "BPLName",1                   FROM ' + @OilDatabase + '.OBPL                    '')';          EXEC sp_executesql @SQL;      SET @SQL = '              INSERT INTO jsBranch (branchId, branchName,company)              SELECT *               FROM OPENQUERY([' + @ServerName + '],                   ''SELECT "BPLId", "BPLName",2                   FROM ' + @BeverageDatabase + '.OBPL                    '')';      SET @SQL = '              INSERT INTO jsBranch (branchId, branchName,company)              SELECT *               FROM OPENQUERY([' + @ServerName + '],                   ''SELECT "BPLId", "BPLName",3                   FROM ' + @MartDatabase + '.OBPL                    '')';          --   -- Draft Approval     --CREATE TABLE #TempTable (        --      Branch NVARCHAR(50),        --      DocEntry INT,        --      ObjectName NVARCHAR(100),        --      ObjType INT,        --      LineNum INT,        --      VisOrder INT,        --      AcctCode NVARCHAR(50),        --      AcctName NVARCHAR(100),        --      CardCode NVARCHAR(50),        --      CardName NVARCHAR(200),        --      EFFECTMONTH NVARCHAR(50),        --      BUDGET NVARCHAR(50),        --      SUB_BUDGET NVARCHAR(50),        --      STATE NVARCHAR(50),        --      DocDate DATETIME,        --      CreateDate DATETIME,        --      trgtPath NVARCHAR(500),        --      FileName NVARCHAR(200),        --      FileExt NVARCHAR(10),        --      AMOUNT DECIMAL(18, 2),        --      CURRENTMONTH NVARCHAR(50),        --      Current_month_Posted_Amount DECIMAL(18, 2),        --      AtcEntry INT,        --      Budget_Owner NVARCHAR(100),        --      OwnerCode NVARCHAR(50),        --      ApproverName NVARCHAR(100),        --      ApprovalCode NVARCHAR(50),        --      Current_month_Budget DECIMAL(18, 2),        --      Status NVARCHAR(10),        --      U_NAME NVARCHAR(100),        --      Creat